import json
P = 'apercu/prototype-op-gestion.html'
def d(n, gravite, ecran, profils, etapes, attendu, constate, preuve, ou, correction, decision, role='client', zone=None, recommandation=None, sonde=None):
    x = dict(n='client-%02d' % n, gravite=gravite, ecran=ecran, role=role, profils=profils, etapes=etapes, attendu=attendu, constate=constate, preuve=preuve, ou=ou, correction=correction, decision=decision)
    if zone: x['zone'] = zone
    if recommandation: x['recommandation'] = recommandation
    if sonde: x['sonde'] = sonde
    return x
